'AC8.15.2'; from __future__ import annotations; from pathlib import Path; from unittest.mock import AsyncMock; from sqlalchemy import select; from src.extraction import BankStatementStatus, ClassificationStatus, DocumentSource, RuleType; from src.extraction.extension.service import ExtractionService; from src.extraction.extension.statement_posting import try_auto_approve_high_confidence_statement; from src.extraction.orm.layer3 import ClassificationRule, TransactionClassification; from src.ledger import Account, AccountType, JournalEntry, JournalEntryStatus; from tests.statement_ingestion import parse_and_load_statement_projection, posting_dependencies; _balanced_bank_payload = lambda: {'institution': 'MariBank', 'account_last4': '8497', 'currency': 'sgd', 'period_start': '2026-05-01', 'period_end': '2026-05-31', 'opening_balance': '1000.00', 'closing_balance': '1090.00', 'transactions': [{'date': '2026-05-10', 'description': 'Interest', 'amount': '90.00', 'direction': 'IN', 'currency': 'sgd', 'balance_after': '1090.00'}]}
async def _apply_reviewed_interest_disposition(db, user_id, transaction) -> None: income = Account(user_id=user_id, name='Income - Interest', code='4102', type=AccountType.INCOME, currency=transaction.currency); db.add(income); await db.flush(); rule = ClassificationRule(user_id=user_id, version_number=1, effective_date=transaction.txn_date, rule_name='Reviewed interest disposition', rule_type=RuleType.KEYWORD_MATCH, rule_config={'keywords': ['interest']}, default_account_id=income.id, created_by=user_id); db.add(rule); await db.flush(); db.add(TransactionClassification(atomic_txn_id=transaction.id, rule_version_id=rule.id, account_id=income.id, tags={'category': 'INTEREST'}, confidence_score=100, status=ClassificationStatus.APPLIED)); await db.flush()
async def test_AC8_15_2_bank_statement_auto_creates_account_and_posts_with_reviewed_disposition(db, test_user): 'AC-reporting.full-year.2'; service = ExtractionService(); service.extract_financial_data = AsyncMock(return_value=_balanced_bank_payload()); _result, statement, transactions = await parse_and_load_statement_projection(service, db=db, source=DocumentSource.resolve(path=Path('mari-2605.pdf'), content=b'%PDF-1.7'), institution='MariBank', user_id=test_user.id); await db.flush(); assert statement.account_id is not None; account = await db.get(Account, statement.account_id); assert account is not None; assert account.type == AccountType.ASSET; assert account.is_active is True; assert account.currency == 'SGD'; assert statement.status == BankStatementStatus.APPROVED; await _apply_reviewed_interest_disposition(db, test_user.id, transactions[0]); posted = await try_auto_approve_high_confidence_statement(db, statement.id, test_user.id, dependencies=posting_dependencies()); assert posted >= 1; posted_entries = (await db.execute(select(JournalEntry).where(JournalEntry.user_id == test_user.id, JournalEntry.status == JournalEntryStatus.POSTED))).scalars().all(); assert len(posted_entries) >= 1
